command:
cd /root/pgca
get_ip() {
  case "$1" in
    node1) echo 10.100.197.10 ;;
    node2) echo 10.100.197.11 ;;
    node3) echo 10.100.197.12 ;;
  esac
}
for n in node1 node2 node3; do
  ip=$(get_ip $n)
  openssl req -new -key ${n}.key -out ${n}.csr -subj "/CN=${n}"
  openssl x509 -req -in ${n}.csr -CA ca.crt -CAkey ca.key -CAcreateserial -out ${n}.crt -days 825 -sha256 \
    -extfile <(printf "subjectAltName=DNS:%s,IP:%s\n" "$n" "$ip")
done
echo ---
for f in node1 node2 node3; do openssl x509 -in ${f}.crt -noout -subject -ext subjectAltName; done

